draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // tree
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/4);
  ctx.stroke();

  // branches
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/4);
  ctx.lineTo(W/4, H/8);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/4);
  ctx.lineTo(W - W/4, H/8);
  ctx.stroke();

  // sitting buddha
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H - H/4, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H - H/4 + 20);
  ctx.lineTo(W/2 - 10, H - H/4 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H - H/4 + 20);
  ctx.lineTo(W/2 + 10, H - H/4 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H - H/4 + 50);
  ctx.lineTo(W/2 + 20, H - H/4 + 50);
  ctx.stroke();

  // morning star
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/8 + Math.cos(t) * 20, 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
